<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('vendors.view');if(is_post()){require_permission('vendors.manage');verify_csrf();$action=(string)input('action');try{$pdo=db();$pdo->beginTransaction();if($action==='vendor'){$code='VND-'.strtoupper(bin2hex(random_bytes(4)));$pdo->prepare('INSERT INTO vendors(vendor_code,name,shop_name,email,mobile,address,status,created_by) VALUES(?,?,?,?,?, ?,"ACTIVE",?)')->execute([$code,trim((string)input('name')),trim((string)input('shop_name')),trim((string)input('email'))?:null,trim((string)input('mobile'))?:null,trim((string)input('address')),admin()['id']]);$record=(string)$pdo->lastInsertId();}elseif($action==='user'){$password=(string)input('password');if(strlen($password)<12)throw new InvalidArgumentException('Vendor password must contain at least 12 characters.');$pdo->prepare('INSERT INTO vendor_users(vendor_id,name,username,email,password_hash,status) VALUES(?,?,?,?,?,"ACTIVE")')->execute([(int)input('vendor_id'),trim((string)input('user_name')),trim((string)input('username')),trim((string)input('user_email'))?:null,password_hash($password,PASSWORD_DEFAULT)]);$record=(string)$pdo->lastInsertId();}elseif($action==='status'){$record=(string)(int)input('vendor_id');$status=strtoupper((string)input('status'));if(!in_array($status,['ACTIVE','BLOCKED','INACTIVE'],true))throw new InvalidArgumentException('Invalid status.');$pdo->prepare('UPDATE vendors SET status=? WHERE id=?')->execute([$status,$record]);}else throw new InvalidArgumentException('Invalid action.');audit_log((int)admin()['id'],'VENDOR_'.strtoupper($action),'vendors',$record??null);$pdo->commit();flash('success','Vendor record saved.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e->getMessage());}redirect('/admin/vendors/index.php');}$vendors=db()->query('SELECT v.*,(SELECT COUNT(*) FROM vendor_users WHERE vendor_id=v.id) users,(SELECT COUNT(*) FROM gift_redemptions WHERE vendor_id=v.id) redemptions FROM vendors v ORDER BY v.id DESC')->fetchAll();$pageTitle='Vendors';$pageSubtitle='Merchant accounts, portal access and redemption status';require APP_ROOT.'/includes/header.php';?>
<?php if(can('vendors.manage')):?><div class="grid detail-grid"><section class="panel"><h2>Add vendor</h2><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="vendor"><input name="name" placeholder="Vendor name" required><input name="shop_name" placeholder="Shop name" required><input type="email" name="email" placeholder="Email"><input name="mobile" placeholder="Mobile"><textarea name="address" placeholder="Address"></textarea><button class="btn">Create vendor</button></form></section><section class="panel"><h2>Add vendor login</h2><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="user"><select name="vendor_id" required><?php foreach($vendors as $v):?><option value="<?=e($v['id'])?>"><?=e($v['shop_name'])?></option><?php endforeach?></select><input name="user_name" placeholder="Staff name" required><input name="username" placeholder="Username" required><input type="email" name="user_email" placeholder="Email"><input type="password" name="password" minlength="12" autocomplete="new-password" placeholder="12+ character password" required><button class="btn">Create login</button></form></section></div><?php endif?>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Code</th><th>Vendor / shop</th><th>Contact</th><th>Users</th><th>Redemptions</th><th>Status</th><th>Change status</th></tr></thead><tbody><?php foreach($vendors as $v):?><tr><td><?=e($v['vendor_code'])?></td><td><?=e($v['name'])?><br><small><?=e($v['shop_name'])?></small></td><td><?=e($v['email']??'—')?><br><?=e($v['mobile']??'—')?></td><td><?=e($v['users'])?></td><td><?=e($v['redemptions'])?></td><td><span class="badge <?=strtolower(e($v['status']))?>"><?=e($v['status'])?></span></td><td><?php if(can('vendors.manage')):?><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="vendor_id" value="<?=e($v['id'])?>"><select name="status"><?php foreach(['ACTIVE','BLOCKED','INACTIVE'] as $st):?><option <?=$v['status']===$st?'selected':''?>><?=e($st)?></option><?php endforeach?></select><button class="btn small">Save</button></form><?php endif?></td></tr><?php endforeach?></tbody></table><?php if(!$vendors):?><div class="empty">No vendors configured.</div><?php endif?></div></section><?php require APP_ROOT.'/includes/footer.php';
